#!/bin/bash
# GENERATED by tools/host_leaf_suite.py gen-script leaf_fewmore_b - edit the @leaf
# markers in leaf_fewmore_b_harness.c, not this file.
# Compiles the unchanged decomp units below, links them with the leaf harness
# and runs the per-function checks under QEMU.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
DECOMP="${DECOMP:-$(cd "$HERE/../.." && pwd)}"
T="${TOOLCHAIN:-$DECOMP/.toolchain}"
OUT="${OUT:-$HERE/build-leaf-fewmore-b}"
QEMU="${QEMU:-$HOME/.local/share/qemu-user/extracted/usr/bin/qemu-mipsel}"
GCC="$T/gcc-2.7.2-cdk/gcc"
MASPSX="$(echo "$T"/maspsx-*/maspsx.py)"
mkdir -p "$OUT"
export PATH="$T/mipsel-binutils/root/usr/bin:$PATH"
export LD_LIBRARY_PATH="$T/mipsel-binutils/root/usr/lib/x86_64-linux-gnu${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"

compile() {
    local src="$1" obj="$2"; shift 2
    "$GCC" -B"$T/gcc-2.7.2-cdk/" -I"$DECOMP/include" -I"$HERE/mocks" "$@" -O1 -G0 -S "$src" -o "$OUT/tmp.s"
    python3 "$MASPSX" "$OUT/tmp.s" | python3 "$HERE/fix_align.py" > "$OUT/tmp.mas.s"
    mipsel-linux-gnu-as -o "$obj" "$OUT/tmp.mas.s"
}

objects=()
for unit in 8002AB8C 8002CB20 8002E528 80033608 8003C500 8003D0F0 80051580 8004DD68 8004DB74 800585B8 8005A190 80067480 8006F21C 8006FB7C 80070048; do
    compile "$DECOMP/src/game/$unit.c" "$OUT/$unit.o"
    objects+=("$OUT/$unit.o")
done
compile "$HERE/mocks/bios_mock.c" "$OUT/bios_mock.o"
python3 "$HERE/leaf_vectors.py" > "$OUT/leaf_vectors.h"
compile "$HERE/leaf_fewmore_b_harness.c" "$OUT/leaf_fewmore_b_harness.o" -I"$OUT" -I"$HERE"
mipsel-linux-gnu-as -o "$OUT/crt0.o" "$HERE/crt0.s" 2>/dev/null
mipsel-linux-gnu-ld -static -e __start -o "$OUT/leaf_fewmore_b" \
    "$OUT/crt0.o" "$OUT/leaf_fewmore_b_harness.o" "$OUT/bios_mock.o" "${objects[@]}"
"$QEMU" "$OUT/leaf_fewmore_b"
